const isHeartbeat = Boolean(msg._heartbeat);
const now = Date.now();

const cfg = {
  proxyToken: env.get('PROXY_TOKEN') || '',
  appKey: env.get('BETFAIR_APP_KEY') || '',
  username: env.get('BETFAIR_USERNAME') || '',
  password: env.get('BETFAIR_PASSWORD') || '',
  bettingUrl: env.get('BETFAIR_BETTING_API_URL') || 'https://api-au.betfair.com/exchange/betting/json-rpc/v1',
  loginUrl: env.get('BETFAIR_LOGIN_URL') || 'https://identitysso.betfair.com.au/api/login',
  maxTokenAgeMs: Number(env.get('BETFAIR_TOKEN_MAX_AGE_MS') || 3.5 * 60 * 60 * 1000),
  breakerThreshold: Number(env.get('BETFAIR_BREAKER_THRESHOLD') || 3),
  breakerCooldownMs: Number(env.get('BETFAIR_BREAKER_COOLDOWN_MS') || 120000),
};

function forHttp(statusCode, payload) {
  msg.statusCode = statusCode;
  msg.payload = payload;
  return [msg, null];
}

function forHeartbeat(payload) {
  msg.payload = payload;
  return [null, msg];
}

if (!cfg.appKey) {
  const out = { ok: false, error: 'Missing BETFAIR_APP_KEY' };
  return isHeartbeat ? forHeartbeat(out) : forHttp(500, out);
}

if (!isHeartbeat) {
  const incomingToken = String(msg.req?.headers?.['x-proxy-token'] || '');
  if (cfg.proxyToken && incomingToken !== cfg.proxyToken) {
    return forHttp(401, { error: 'Unauthorized proxy token' });
  }
}

const payload = msg.payload && typeof msg.payload === 'object' ? msg.payload : {};
const method = String(payload.method || '').trim();
const params = payload.params && typeof payload.params === 'object' ? payload.params : {};

const rpcMethod = method || (isHeartbeat ? 'listEventTypes' : '');
const rpcParams = method ? params : (isHeartbeat ? { filter: {} } : {});

if (!rpcMethod) {
  return forHttp(400, { error: 'method is required' });
}

const breaker = global.get('bf_breaker') || { failCount: 0, openUntil: 0 };
if (breaker.openUntil > now && !isHeartbeat) {
  return forHttp(503, {
    error: 'Circuit breaker open',
    retryAfterMs: breaker.openUntil - now,
    failCount: breaker.failCount,
  });
}

const tokenMeta = global.get('bf_token_meta') || { obtainedAt: 0, lastRefreshAt: 0 };

async function loginInteractive() {
  if (!cfg.username || !cfg.password) {
    throw new Error('Missing BETFAIR_USERNAME/BETFAIR_PASSWORD for token refresh');
  }

  const body = new URLSearchParams({ username: cfg.username, password: cfg.password });
  const response = await fetch(cfg.loginUrl, {
    method: 'POST',
    headers: {
      Accept: 'application/json',
      'Content-Type': 'application/x-www-form-urlencoded',
      'X-Application': cfg.appKey,
    },
    body: body.toString(),
  });

  const raw = await response.text();
  let parsed = null;
  try {
    parsed = raw ? JSON.parse(raw) : null;
  } catch (e) {
    throw new Error(`Login returned non-JSON (${response.status})`);
  }

  const status = String(parsed?.status || '').toUpperCase();
  if (!response.ok || !parsed?.token || !['SUCCESS', 'LIMITED_ACCESS'].includes(status)) {
    throw new Error(`Login failed (${response.status}): ${parsed?.status || 'UNKNOWN'} ${parsed?.error || ''}`.trim());
  }

  global.set('betfairToken', parsed.token);
  const nextMeta = { obtainedAt: Date.now(), lastRefreshAt: Date.now() };
  global.set('bf_token_meta', nextMeta);
  return parsed.token;
}

function needsRefresh(currentToken) {
  if (!currentToken) return true;
  const age = Date.now() - Number(tokenMeta.obtainedAt || 0);
  return age > cfg.maxTokenAgeMs;
}

async function ensureToken() {
  const existing = String(global.get('betfairToken') || env.get('BETFAIR_SESSION_TOKEN') || '');
  if (needsRefresh(existing)) {
    return loginInteractive();
  }
  return existing;
}

async function callBetfair(token) {
  const started = Date.now();
  const response = await fetch(cfg.bettingUrl, {
    method: 'POST',
    headers: {
      Accept: 'application/json',
      'Content-Type': 'application/json',
      'X-Application': cfg.appKey,
      'X-Authentication': token,
    },
    body: JSON.stringify({
      jsonrpc: '2.0',
      method: `SportsAPING/v1.0/${rpcMethod}`,
      params: rpcParams,
      id: 1,
    }),
  });

  const raw = await response.text();
  const contentType = String(response.headers.get('content-type') || '');
  let parsed = null;
  let parseError = null;
  try {
    parsed = raw ? JSON.parse(raw) : null;
  } catch (e) {
    parseError = e;
  }

  const envelope = Array.isArray(parsed) ? parsed[0] : parsed;
  const message = String(envelope?.error?.message || raw || 'Unknown error');
  const authError = /ANGX-0003|INVALID_SESSION_INFORMATION|NO_SESSION/i.test(message);

  return {
    ok: response.ok && !envelope?.error && !parseError,
    status: response.status,
    contentType,
    raw,
    parsed,
    authError,
    parseError: Boolean(parseError),
    durationMs: Date.now() - started,
    message,
  };
}

(async () => {
  const reqId = `${Date.now()}-${Math.random().toString(16).slice(2, 8)}`;
  try {
    let token = await ensureToken();
    let call = await callBetfair(token);
    let retried = false;

    if (!call.ok && call.authError) {
      token = await loginInteractive();
      call = await callBetfair(token);
      retried = true;
    }

    if (call.ok) {
      global.set('bf_breaker', { failCount: 0, openUntil: 0, lastOkAt: Date.now() });
      const resultEnvelope = Array.isArray(call.parsed) ? call.parsed[0] : call.parsed;
      const result = resultEnvelope?.result !== undefined ? resultEnvelope.result : call.parsed;
      const telemetry = {
        ok: true,
        reqId,
        method: rpcMethod,
        retried,
        status: call.status,
        contentType: call.contentType,
        durationMs: call.durationMs,
        tokenAgeSec: Math.floor((Date.now() - Number((global.get('bf_token_meta') || {}).obtainedAt || 0)) / 1000),
      };

      if (isHeartbeat) {
        node.warn(`heartbeat ok ${JSON.stringify(telemetry)}`);
        node.send(forHeartbeat(telemetry));
      } else {
        node.send(forHttp(200, { result, telemetry }));
      }
      node.done();
      return;
    }

    const failCount = Number((breaker.failCount || 0) + 1);
    const openUntil = failCount >= cfg.breakerThreshold ? Date.now() + cfg.breakerCooldownMs : 0;
    global.set('bf_breaker', { failCount, openUntil, lastFailAt: Date.now(), lastError: call.message });

    const errorPayload = {
      error: 'Betfair upstream failure',
      reqId,
      method: rpcMethod,
      retried,
      status: call.status,
      contentType: call.contentType,
      message: call.message,
      parseError: call.parseError,
      breaker: { failCount, openUntil },
      durationMs: call.durationMs,
    };

    if (isHeartbeat) {
      node.warn(`heartbeat fail ${JSON.stringify(errorPayload)}`);
      node.send(forHeartbeat(errorPayload));
    } else {
      node.send(forHttp(502, errorPayload));
    }
    node.done();
  } catch (error) {
    const failCount = Number((breaker.failCount || 0) + 1);
    const openUntil = failCount >= cfg.breakerThreshold ? Date.now() + cfg.breakerCooldownMs : 0;
    global.set('bf_breaker', { failCount, openUntil, lastFailAt: Date.now(), lastError: String(error?.message || error) });

    const payload = {
      error: String(error?.message || error),
      method: rpcMethod,
      breaker: { failCount, openUntil },
    };

    if (isHeartbeat) {
      node.warn(`heartbeat exception ${JSON.stringify(payload)}`);
      node.send(forHeartbeat(payload));
    } else {
      node.send(forHttp(500, payload));
    }
    node.done();
  }
})();

return;
